mapper.select:
SELECT * FROM risk_rule
WHERE region = #{region}
  AND scene = #{scene}
  AND enabled = TRUE
  AND is_deleted = FALSE
ORDER BY id ASC

SELECT * FROM risk_rule
WHERE id = #{id}
  AND region = #{region}
  AND is_deleted = FALSE

mapper.sql:
WHERE region = #{region}
AND scene = #{scene}
AND decision = #{decision}
AND dispose_status = #{disposeStatus}

mapper.select:
SELECT * FROM risk_event

ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

choose.when:
SELECT COUNT(*) FROM review
WHERE user_id = #{userId}
  AND region = #{region}
  AND is_deleted = FALSE

    AND created_at >= DATEADD('SECOND', -#{windowSeconds}, CURRENT_TIMESTAMP)

SELECT COUNT(*) FROM `order`
WHERE user_id = #{userId}
  AND region = #{region}

    AND created_at >= DATEADD('SECOND', -#{windowSeconds}, CURRENT_TIMESTAMP)

mapper.select:
SELECT content FROM review
WHERE user_id = #{userId}
  AND region = #{region}
  AND is_deleted = FALSE
ORDER BY created_at DESC, id DESC
LIMIT #{limit}
